import OutputSection from '@/routes/_authenticated/f/output/-components/OutputSection/OutputSection';
import { createFileRoute, Navigate, useNavigate } from '@tanstack/react-router';
import { z } from 'zod';
import { StyledFunnelContentWrapper } from '@/routes/_authenticated/f/-route.style';
import { useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getProductFileStatusPollingOptions } from '@/query/options/products';
import {
  clearFunnelSession,
  readOutputFunnelContext,
  writeOutputFunnelContext
} from '@/routes/_authenticated/f/-funnelStorage';
export const Route = createFileRoute('/_authenticated/f/output/$productFileId')(
  {
    component: RouteComponent,
    validateSearch: z.object({
      fileName: z.string().optional(),
      templateFileId: z.string().optional()
    })
  }
);

function RouteComponent() {
  const { productFileId } = Route.useParams();
  const search = Route.useSearch();
  const navigate = useNavigate();
  const { data: statusData } = useQuery(
    getProductFileStatusPollingOptions(productFileId)
  );
  const existingOutputContext = readOutputFunnelContext();
  const canonicalProductFileId = statusData?.data.productFileId;
  const existingTemplateFileId = existingOutputContext?.templateFileId;
  const existingFileName = existingOutputContext?.fileName;

  useEffect(() => {
    if (!canonicalProductFileId || canonicalProductFileId === productFileId) {
      return;
    }

    void navigate({
      to: '/f/output/$productFileId',
      params: { productFileId: canonicalProductFileId },
      search,
      replace: true
    });
  }, [canonicalProductFileId, navigate, productFileId, search]);

  useEffect(() => {
    if (!canonicalProductFileId || canonicalProductFileId !== productFileId) {
      return;
    }

    if (statusData?.data.status === 'COMPLETED') {
      clearFunnelSession();
      return;
    }

    writeOutputFunnelContext({
      productFileId: canonicalProductFileId,
      templateFileId: search.templateFileId ?? existingTemplateFileId,
      fileName: search.fileName ?? existingFileName
    });
  }, [
    canonicalProductFileId,
    existingFileName,
    existingTemplateFileId,
    statusData?.data.status,
    productFileId,
    search.fileName,
    search.templateFileId
  ]);

  if (!productFileId) {
    return <Navigate to="/f/template" />;
  }

  return (
    <StyledFunnelContentWrapper>
      <OutputSection productFileId={productFileId} />
    </StyledFunnelContentWrapper>
  );
}
