import { useEffect, useMemo, useRef } from 'react';
import { useTheme } from '@emotion/react';
import { useNavigate } from '@tanstack/react-router';
import { StyledGenCenter } from '@/routes/_authenticated/start/-route.style';
import { GenerateInProgressScreen } from '@/routes/_authenticated/-components/GenerateInProgressScreen/GenerateInProgressScreen';
import { GENERATE_PROGRESS_STEP_COUNT } from '@/routes/_authenticated/-components/GenerateInProgressScreen/GenerateInProgressScreen.constants';
import { useOutputSection } from '@/routes/_authenticated/f/output/-components/OutputSection/OutputSection.hook';
import { clearFunnelSession } from '@/routes/_authenticated/f/-funnelStorage';

interface OutputSectionProps {
  productFileId: string;
}

export default function OutputSection({ productFileId }: OutputSectionProps) {
  const theme = useTheme();
  const navigate = useNavigate();
  const hasNavigatedRef = useRef(false);
  const {
    statusData,
    error,
    isStatusCompleted,
    isStatusFailed,
    isProcessing
  } = useOutputSection(productFileId);

  const currentStep = useMemo(() => {
    switch (statusData?.data.status) {
      case 'PENDING':
        return 1;
      case 'PROGRESS':
        return 3;
      case 'COMPLETED':
        return GENERATE_PROGRESS_STEP_COUNT;
      default:
        return 0;
    }
  }, [statusData?.data.status]);

  useEffect(() => {
    const nextProductFileId = statusData?.data.productFileId ?? productFileId;

    if (!isStatusCompleted || hasNavigatedRef.current) {
      return;
    }

    hasNavigatedRef.current = true;
    clearFunnelSession();
    void navigate({
      to: '/d/$productFileId',
      params: { productFileId: String(nextProductFileId) },
      search: { fromGenerate: true }
    });
  }, [isStatusCompleted, navigate, productFileId, statusData?.data.productFileId]);

  const handleGoHome = () => {
    navigate({ to: '/f/template' });
  };

  if (isStatusFailed) {
    return (
      <StyledGenCenter>
        <div
          style={{
            width: 64,
            height: 64,
            borderRadius: '50%',
            background: '#F04452',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            marginBottom: 24
          }}
        >
          <span style={{ color: '#FFFFFF', fontSize: 28, fontWeight: 700 }}>
            !
          </span>
        </div>
        <h2
          style={{
            fontSize: 20,
            fontWeight: 600,
            marginBottom: 12,
            letterSpacing: '-0.02em',
            color: '#25262C'
          }}
        >
          사업계획서 생성에 실패했습니다
        </h2>
        <p
          style={{
            fontSize: 14,
            color: '#B5B9C4',
            textAlign: 'center',
            lineHeight: 1.6,
            marginBottom: 32,
            letterSpacing: '-0.02em'
          }}
        >
          잠시 후 다시 시도해주세요.
        </p>
        <button
          type="button"
          onClick={handleGoHome}
          style={{
            background: 'none',
            border: 'none',
            color: theme.color.textGray,
            fontSize: 14,
            cursor: 'pointer',
            padding: '8px 16px',
            letterSpacing: '-0.02em'
          }}
        >
          처음으로
        </button>
      </StyledGenCenter>
    );
  }

  if (error) {
    throw new Error(error.message);
  }

  if (!productFileId) {
    return null;
  }

  if (!isProcessing && !isStatusCompleted) {
    return null;
  }

  return <GenerateInProgressScreen currentStep={currentStep} />;
}
